  add('titleFr',t.titleFr,'text',true);add('titleEn',t.titleEn,'text',true);add('descriptionFr',t.descriptionFr,'textarea',true);add('descriptionEn',t.descriptionEn,'textarea',true);add('circuit',t.circuit,'text',true);
  add('startsAt',t.startsAt,'datetime-local',true);add('serverOpensAt',t.serverOpensAt,'datetime-local');form.append(el('p','profile-note',t.dateHint));
  add('practiceMinutes',t.practice,'number');add('qualifyingMinutes',t.qualifying,'number');add('raceMinutes',t.race,'number',true);add('maxDrivers',t.maxDrivers,'number',true);add('registered',t.registered,'number');add('carClass',t.carClass);add('imageUrl',t.image,'url',true);add('simgridUrl',t.register,'url',values.competition!=='ATXS');
  const comp=choice('competition',t.competition,values.competition==='BATX'?['DR','WGT','ATXS','BATX']:['DR','WGT','ATXS']);const format=choice('format',t.format,formats[values.competition]||[]);comp.onchange=()=>{format.replaceChildren();const blank=el('option','',t.choose);blank.value='';format.append(blank);for(const item of formats[comp.value]||[]){const option=el('option','',item.replace('_',' '));option.value=item;format.append(option);}fields.simgridUrl.required=comp.value!=='ATXS';if(comp.value==='ATXS'){format.value='ATXS';[fields.practiceMinutes.value,fields.qualifyingMinutes.value,fields.raceMinutes.value]=[2,15,45];}};format.addEventListener('change',()=>{if(preset[format.value])[fields.practiceMinutes.value,fields.qualifyingMinutes.value,fields.raceMinutes.value]=preset[format.value];});
